/**
 * Time as "HH:MM", 24-hour, zero-padded ("09:30", "23:05"). Chosen so
 * values compare and sort as strings, round-trip through JSON cleanly,
 * and never carry a time zone — a time of day is not an instant.
 */
export type Time = string;

/** True when t is a well-formed 24h time string. */
export function isValidTime(t: unknown): t is Time {
  if (typeof t !== "string") return false;
  const m = /^(\d{2}):(\d{2})$/.exec(t);
  if (!m) return false;
  const h = Number(m[1]);
  const mm = Number(m[2]);
  return h >= 0 && h <= 23 && mm >= 0 && mm <= 59;
}

/** Build an HH:MM from numeric h/m, zero-padded. */
export function makeTime(h: number, m: number): Time {
  const hh = Math.max(0, Math.min(23, Math.floor(h)));
  const mm = Math.max(0, Math.min(59, Math.floor(m)));
  return `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
}

/** Split an HH:MM into { h, m }. Assumes the input is valid. */
export function parseTime(t: Time): { h: number; m: number } {
  return { h: Number(t.slice(0, 2)), m: Number(t.slice(3, 5)) };
}

/** Compare two times. Negative if a < b, 0 if equal, positive if a > b. */
export function compareTime(a: Time, b: Time): number {
  return a.localeCompare(b);
}

/** Minutes since 00:00 (useful for duration maths). */
export function toMinutes(t: Time): number {
  const { h, m } = parseTime(t);
  return h * 60 + m;
}

/** Build an HH:MM from minutes since 00:00; wraps on 24h overflow. */
export function fromMinutes(n: number): Time {
  const total = ((n % 1440) + 1440) % 1440;
  return makeTime(Math.floor(total / 60), total % 60);
}

/** The current time rounded down to the given step (default 1 minute). */
export function nowTime(step = 1): Time {
  const d = new Date();
  const m = d.getHours() * 60 + d.getMinutes();
  return fromMinutes(Math.floor(m / step) * step);
}

/**
 * Parse user input into HH:MM, forgiving of common formats:
 *   "9:30 am"  → "09:30"
 *   "9 pm"     → "21:00"
 *   "0930"     → "09:30"
 *   "14:5"     → "14:05"
 *   "14.30"    → "14:30"
 *   "9"        → "09:00"
 *   "2330"     → "23:30"
 * Returns null when the input can't be read as a time.
 */
export function parseTimeInput(raw: string): Time | null {
  const text = raw.trim().toLowerCase();
  if (!text) return null;

  // Pull off a trailing am/pm (optionally with a dot: "a.m.").
  let suffix: "am" | "pm" | null = null;
  let body = text;
  const sfx = /\s*(a\.?m\.?|p\.?m\.?)\s*$/.exec(body);
  if (sfx) {
    suffix = sfx[1].startsWith("a") ? "am" : "pm";
    body = body.slice(0, body.length - sfx[0].length).trim();
  }

  // Split by any non-digit separator; also accept compact "0930" or "930".
  let hStr: string;
  let mStr: string;
  const parts = body.split(/[^\d]+/).filter(Boolean);
  if (parts.length >= 2) {
    hStr = parts[0];
    mStr = parts[1];
  } else if (parts.length === 1) {
    const only = parts[0];
    if (only.length <= 2) {
      // "9" or "14": hour only, no minutes.
      hStr = only;
      mStr = "0";
    } else if (only.length === 3) {
      // "930" → 9:30
      hStr = only.slice(0, 1);
      mStr = only.slice(1);
    } else if (only.length === 4) {
      // "0930" → 09:30
      hStr = only.slice(0, 2);
      mStr = only.slice(2);
    } else {
      return null;
    }
  } else {
    return null;
  }

  let h = Number(hStr);
  const m = Number(mStr);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
  if (m < 0 || m > 59) return null;

  if (suffix) {
    if (h < 1 || h > 12) return null;
    if (suffix === "am") h = h === 12 ? 0 : h;
    else h = h === 12 ? 12 : h + 12;
  } else {
    if (h < 0 || h > 23) return null;
  }

  return makeTime(h, m);
}

/**
 * Format HH:MM for display in the input. 24h returns as-is; 12h returns
 * "9:30 AM" style, with no padding on the hour.
 */
export function formatTimeInput(t: Time | null, format: "12h" | "24h"): string {
  if (!t) return "";
  const { h, m } = parseTime(t);
  if (format === "24h") return t;
  const period = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2, "0")} ${period}`;
}

/**
 * Snap a time to the nearest multiple of step minutes (default round down).
 * Used when a user types "9:17" into a 15-minute-step field.
 */
export function snapTime(t: Time, step: number, mode: "floor" | "round" | "ceil" = "floor"): Time {
  if (step <= 1) return t;
  const n = toMinutes(t);
  const f = mode === "ceil" ? Math.ceil : mode === "round" ? Math.round : Math.floor;
  return fromMinutes(f(n / step) * step);
}

.root {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: 180px;
}

.input {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.open {
  border-color: var(--field-focus-border, rgba(var(--rgb-brand), 0.7));
  box-shadow: var(--field-focus-ring, var(--focus-halo));
}

.toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-right: 5px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  color: var(--ink-muted);
  transition:
    color var(--dur) var(--ease),
    background-color var(--dur) var(--ease);
}

.toggle:hover:not(:disabled),
.toggle[aria-expanded="true"] {
  color: var(--ink-brand);
  background: var(--wash-subtle);
}

.toggle:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--field-focus-border, var(--focus-color));
}

.toggle:disabled {
  cursor: not-allowed;
  color: var(--ink-disabled);
}

.problem {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--danger-ink);
}

.problem svg {
  margin-top: 1px;
  flex-shrink: 0;
}

/* Popup: three scrollable columns (hours : minutes [AM/PM]) on a floating
   solid surface. Each column shows a fixed window with its selected cell
   centered on open, which makes the picker feel like a wheel without the
   accessibility cost of a real pointer-wheel. */
.popup {
  position: fixed;
  z-index: var(--z-popover);
  padding: 8px;
  background: var(--surface-solid);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-float);
  animation: time-pop-in var(--dur) var(--ease-out);
}

@keyframes time-pop-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
}

.body {
  display: flex;
  align-items: stretch;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.col {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 56px;
  height: 220px;
  padding: 4px;
  overflow-y: auto;
  scrollbar-width: thin;
  scroll-behavior: smooth;
  /* A soft inner groove so each column reads as its own track, not three
     cells floating against the popup surface. */
  background: var(--surface-sunken);
  border-radius: var(--r-sm);
}

.periodCol {
  width: 52px;
}

.sep {
  display: inline-flex;
  align-items: center;
  padding-bottom: 2px;
  font-size: 20px;
  font-weight: 700;
  color: var(--ink-muted);
}

.cell {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 32px;
  padding: 0 6px;
  border: 0;
  border-radius: var(--r-xs);
  background: transparent;
  font-size: var(--text-small);
  font-weight: 600;
  color: var(--ink-body);
  cursor: pointer;
  transition:
    background-color var(--dur) var(--ease),
    color var(--dur) var(--ease);
}

.cell:hover:not(:disabled) {
  background: var(--wash-hover);
  color: var(--ink-heading);
}

.cell:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--focus-color);
}

.cell:disabled {
  color: var(--ink-disabled);
  cursor: not-allowed;
}

.cellActive {
  background: var(--wash-active);
  color: var(--ink-brand);
}

.cellActive:hover:not(:disabled) {
  background: var(--wash-active);
  color: var(--ink-brand);
}

/* Inline mode: popup rendered under the field for docs and thumbnails. */
.rootInline {
  display: inline-flex;
  max-width: none;
  flex-direction: column;
  gap: 6px;
}

.popupInline[class] {
  position: static;
  animation: none;
}

/* Range: start | – | end on one row. The dash absorbs its own baseline
   so it sits with the inputs instead of hugging the top. */
.range {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.range > .root {
  max-width: 160px;
}

.rangeSep {
  color: var(--ink-muted);
  font-weight: 700;
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { placePopup } from "../_internal/position";
import { mergeDescribedBy, useField } from "../Field/Field";
import { IconAlertCircle, IconClock } from "../Icon/Icon";
import boxStyles from "../TextInput/TextInput.module.css";
import {
  compareTime,
  formatTimeInput,
  makeTime,
  parseTime,
  parseTimeInput,
  snapTime,
  toMinutes,
  type Time,
} from "./time-utils";
import styles from "./TimeField.module.css";

export type TimeFieldProps = {
  value: Time | null;
  /** null when cleared or when the typed text can't be read as a time. */
  onChange: (value: Time | null) => void;
  /** 24h is the default. 12h shows "9:30 AM" and parses am/pm. */
  format?: "12h" | "24h";
  /** Minute granularity for the popup list (default 15). Set to 1 for a free picker. */
  step?: number;
  min?: Time;
  max?: Time;
  invalid?: boolean;
  disabled?: boolean;
  required?: boolean;
  id?: string;
  name?: string;
  placeholder?: string;
  "aria-label"?: string;
  className?: string;
  /** Keep the popup rendered open under the field (for docs). */
  inline?: boolean;
};

/**
 * A time of day with a typed field and a popup picker. Typing is the fast
 * path when you already know the time ("3pm", "0930", "14:30"); the picker
 * lists times at `step` minutes between `min` and `max` for people who want
 * to click. The value is "HH:MM" 24h regardless of display format, so it
 * sorts, compares and serialises predictably.
 */
export function TimeField({
  value,
  onChange,
  format = "24h",
  step = 15,
  min,
  max,
  invalid: invalidProp,
  disabled,
  required,
  id: idProp,
  name,
  placeholder,
  "aria-label": ariaLabel,
  className,
  inline = false,
}: TimeFieldProps) {
  const field = useField();
  const autoId = useId();
  const id = idProp ?? field?.id ?? `time-${autoId}`;
  const problemId = `${id}-format`;

  const [draft, setDraft] = useState(formatTimeInput(value, format));
  const [synced, setSynced] = useState<Time | null>(value);
  const [problem, setProblem] = useState<string | null>(null);
  const [openState, setOpen] = useState(false);
  const open = inline || openState;

  // Adopt a new value from the parent (reset, prefill) without an effect.
  if (value !== synced) {
    setSynced(value);
    setDraft(formatTimeInput(value, format));
    setProblem(null);
  }

  const boxRef = useRef<HTMLDivElement>(null);
  const toggleRef = useRef<HTMLButtonElement>(null);
  const popupRef = useRef<HTMLDivElement>(null);
  const invalid = invalidProp ?? (Boolean(field?.invalid) || Boolean(problem));
  const defaultPlaceholder = format === "12h" ? "9:30 AM" : "HH:MM";

  const reason = (t: Time): string | null => {
    if (min && compareTime(t, min) < 0) return `Enter a time on or after ${formatTimeInput(min, format)}.`;
    if (max && compareTime(t, max) > 0) return `Enter a time on or before ${formatTimeInput(max, format)}.`;
    return null;
  };

  const commitText = () => {
    const text = draft.trim();
    if (!text) {
      setProblem(null);
      if (value !== null) {
        setSynced(null);
        onChange(null);
      }
      return;
    }
    const parsed = parseTimeInput(text);
    const snapped = parsed ? snapTime(parsed, step, "round") : null;
    const why = snapped ? reason(snapped) : "Enter a time like 9:30 or 14:30.";
    if (!snapped || why) {
      setProblem(why);
      setSynced(null);
      if (value !== null) onChange(null);
      return;
    }
    setProblem(null);
    setDraft(formatTimeInput(snapped, format));
    setSynced(snapped);
    if (snapped !== value) onChange(snapped);
  };

  const pick = (t: Time) => {
    setProblem(null);
    setDraft(formatTimeInput(t, format));
    setSynced(t);
    onChange(t);
    setOpen(false);
    if (!inline) toggleRef.current?.focus();
  };

  const closePopup = (returnFocus: boolean) => {
    setOpen(false);
    if (returnFocus) toggleRef.current?.focus();
  };

  useLayoutEffect(() => {
    if (!open || inline) return;
    const box = boxRef.current;
    const popup = popupRef.current;
    if (!box || !popup) return;
    const place = () => placePopup(box, popup, { align: "start" });
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [open, inline]);

  useEffect(() => {
    if (!open || inline) return;
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node;
      if (boxRef.current?.contains(target) || popupRef.current?.contains(target)) return;
      setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open, inline]);

  const onPopupKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      closePopup(true);
    }
  };

  const popup = (
    <div
      ref={popupRef}
      role="dialog"
      aria-label="Choose time"
      className={cx(styles.popup, inline && styles.popupInline)}
      onKeyDown={onPopupKeyDown}
    >
      <TimePickerBody value={value} onPick={pick} step={step} format={format} min={min} max={max} />
    </div>
  );

  return (
    <div data-slot="time-field" className={cx(styles.root, inline && styles.rootInline, className)}>
      <div
        ref={boxRef}
        className={cx(boxStyles.box, boxStyles.md, invalid && boxStyles.invalid, disabled && boxStyles.disabled, open && styles.open)}
      >
        <input
          id={id}
          name={name}
          type="text"
          inputMode="numeric"
          autoComplete="off"
          className={cx(boxStyles.input, styles.input)}
          placeholder={placeholder ?? defaultPlaceholder}
          value={draft}
          disabled={disabled}
          required={required ?? field?.required}
          aria-label={ariaLabel}
          aria-invalid={invalid || undefined}
          aria-describedby={mergeDescribedBy(field?.describedBy, problem ? problemId : undefined)}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={commitText}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              commitText();
            } else if (e.key === "ArrowDown" && e.altKey) {
              e.preventDefault();
              setOpen(true);
            }
          }}
        />
        <button
          ref={toggleRef}
          type="button"
          className={styles.toggle}
          onClick={() => {
            if (inline) return;
            if (open) closePopup(false);
            else setOpen(true);
          }}
          disabled={disabled}
          aria-label={open ? "Close time picker" : "Choose time from list"}
          aria-haspopup="dialog"
          aria-expanded={open}
        >
          <IconClock size={16} />
        </button>
      </div>

      {problem ? (
        <p id={problemId} className={styles.problem}>
          <IconAlertCircle size={14} />
          <span>{problem}</span>
        </p>
      ) : null}

      {open ? (inline ? popup : <Portal>{popup}</Portal>) : null}
    </div>
  );
}

/**
 * The popup body: hour and minute columns side by side (plus AM/PM when
 * format is "12h"), each a scrollable list auto-centered on the current
 * value. Clicking a cell picks that time and closes the popup.
 */
function TimePickerBody({
  value,
  onPick,
  step,
  format,
  min,
  max,
}: {
  value: Time | null;
  onPick: (t: Time) => void;
  step: number;
  format: "12h" | "24h";
  min?: Time;
  max?: Time;
}) {
  const hoursRef = useRef<HTMLDivElement>(null);
  const minutesRef = useRef<HTMLDivElement>(null);
  const periodRef = useRef<HTMLDivElement>(null);

  const current = value ?? makeTime(new Date().getHours(), 0);
  const { h: curH, m: curM } = parseTime(current);

  // Hour choices depend on format: 1-12 for 12h (with period column), 0-23 for 24h.
  const hourChoices = format === "12h" ? Array.from({ length: 12 }, (_, i) => i + 1) : Array.from({ length: 24 }, (_, i) => i);
  const minuteChoices = Array.from({ length: Math.ceil(60 / step) }, (_, i) => i * step);
  const periodChoices = format === "12h" ? (["AM", "PM"] as const) : null;

  const activeHour12 = curH % 12 === 0 ? 12 : curH % 12;
  const activeHour = format === "12h" ? activeHour12 : curH;
  const activePeriod: "AM" | "PM" = curH >= 12 ? "PM" : "AM";

  const buildTime = (h: number, m: number, p: "AM" | "PM" | null): Time => {
    let H = h;
    if (format === "12h" && p) {
      if (p === "AM") H = h === 12 ? 0 : h;
      else H = h === 12 ? 12 : h + 12;
    }
    return makeTime(H, m);
  };

  const isDisabled = (t: Time) => {
    if (min && compareTime(t, min) < 0) return true;
    if (max && compareTime(t, max) > 0) return true;
    return false;
  };

  // Scroll the three columns so the active cell is centered when the popup opens.
  useLayoutEffect(() => {
    const scrollActiveIntoCenter = (col: HTMLDivElement | null) => {
      if (!col) return;
      const active = col.querySelector<HTMLElement>("[data-active='true']");
      if (!active) return;
      const colBox = col.getBoundingClientRect();
      const activeBox = active.getBoundingClientRect();
      col.scrollTop += activeBox.top - colBox.top - colBox.height / 2 + activeBox.height / 2;
    };
    scrollActiveIntoCenter(hoursRef.current);
    scrollActiveIntoCenter(minutesRef.current);
    scrollActiveIntoCenter(periodRef.current);
  }, []);

  return (
    <div className={styles.body}>
      <div ref={hoursRef} className={styles.col} role="listbox" aria-label="Hour">
        {hourChoices.map((h) => {
          const t = buildTime(h, curM, format === "12h" ? activePeriod : null);
          const active = h === activeHour;
          const dis = isDisabled(t);
          return (
            <button
              key={h}
              type="button"
              role="option"
              aria-selected={active}
              data-active={active || undefined}
              disabled={dis}
              className={cx(styles.cell, active && styles.cellActive)}
              onClick={() => onPick(t)}
            >
              {String(h).padStart(2, "0")}
            </button>
          );
        })}
      </div>

      <div className={styles.sep} aria-hidden="true">:</div>

      <div ref={minutesRef} className={styles.col} role="listbox" aria-label="Minute">
        {minuteChoices.map((m) => {
          const t = buildTime(activeHour, m, format === "12h" ? activePeriod : null);
          const active = m === curM || (step > 1 && Math.abs(m - curM) < step && m <= curM);
          const dis = isDisabled(t);
          return (
            <button
              key={m}
              type="button"
              role="option"
              aria-selected={active}
              data-active={active || undefined}
              disabled={dis}
              className={cx(styles.cell, active && styles.cellActive)}
              onClick={() => onPick(t)}
            >
              {String(m).padStart(2, "0")}
            </button>
          );
        })}
      </div>

      {periodChoices ? (
        <div ref={periodRef} className={cx(styles.col, styles.periodCol)} role="listbox" aria-label="AM or PM">
          {periodChoices.map((p) => {
            const t = buildTime(activeHour, curM, p);
            const active = p === activePeriod;
            const dis = isDisabled(t);
            return (
              <button
                key={p}
                type="button"
                role="option"
                aria-selected={active}
                data-active={active || undefined}
                disabled={dis}
                className={cx(styles.cell, active && styles.cellActive)}
                onClick={() => onPick(t)}
              >
                {p}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

// ── Range ────────────────────────────────────────────────────────────────

export type TimeRange = { start: Time | null; end: Time | null };

export type TimeRangeFieldProps = {
  value: TimeRange;
  onChange: (value: TimeRange) => void;
  format?: "12h" | "24h";
  step?: number;
  /** When true, flag an end at or before start as invalid. Default true. */
  requireEndAfterStart?: boolean;
  min?: Time;
  max?: Time;
  disabled?: boolean;
  className?: string;
  "aria-label-start"?: string;
  "aria-label-end"?: string;
};

/**
 * Start + end pair, laid out on one row with an en dash between the two
 * fields. Flags "end at or before start" as a problem on the end field
 * so the whole row visibly disagrees; the parent can rely on both values
 * being present and ordered before accepting a submit.
 */
export function TimeRangeField({
  value,
  onChange,
  format = "24h",
  step = 15,
  requireEndAfterStart = true,
  min,
  max,
  disabled,
  className,
  "aria-label-start": ariaStart = "Start time",
  "aria-label-end": ariaEnd = "End time",
}: TimeRangeFieldProps) {
  const { start, end } = value;
  const endInvalid =
    requireEndAfterStart && start !== null && end !== null && toMinutes(end) <= toMinutes(start);

  return (
    <div className={cx(styles.range, className)} data-slot="time-range-field">
      <TimeField
        aria-label={ariaStart}
        value={start}
        onChange={(t) => onChange({ start: t, end })}
        format={format}
        step={step}
        min={min}
        max={max}
        disabled={disabled}
      />
      <span className={styles.rangeSep} aria-hidden="true">
        &ndash;
      </span>
      <TimeField
        aria-label={ariaEnd}
        value={end}
        onChange={(t) => onChange({ start, end: t })}
        format={format}
        step={step}
        min={start ?? min}
        max={max}
        invalid={endInvalid || undefined}
        disabled={disabled}
      />
    </div>
  );
}
